import std.io
import std.process

pub fn main() effect io -> Result<(), process.ProcessError> {
    match process.run("/bin/false", []) {
        Ok(pr) => {
            io.println("out:${pr.stdout}")
            io.println("code ${pr.exitCode}")
        }
        Err(_) => { io.println("bad") }
    }
    return Ok(())
}
